{
  "name": "nagara-spike-xs-pipeline",
  "main": "src/index.ts",
  "compatibility_date": "2026-09-01",
  "workflows": [
    { "name": "nagara-spike-xs-item", "binding": "ITEM", "class_name": "ItemWorkflow" }
  ]
}
E
cat > pipeline/src/index.ts <<'E'
import { WorkflowEntrypoint, WorkflowStep, WorkflowEvent } from "cloudflare:workers";

const VERSION = "v1";

export class ItemWorkflow extends WorkflowEntrypoint<Env, { note?: string }> {
  async run(event: WorkflowEvent<{ note?: string }>, step: WorkflowStep) {
    const a = await step.do("a", async () => ({ at: Date.now(), version: VERSION }));
    await step.sleep("nap", "60 seconds");
    const b = await step.do("b", async () => ({ at: Date.now(), version: VERSION }));
    const c = await step.do("c", async () => ({ at: Date.now(), version: VERSION }));
    return { a, b, c, id: event.instanceId };
  }
}

export default {
  async fetch(req: Request, env: Env) {
    const id = new URL(req.url).searchParams.get("id");
    if (id == null) return new Response("pipeline up " + VERSION);
    return Response.json(await (await env.ITEM.get(id)).status());
  },
};
E
cat > api/wrangler.jsonc <<'E'
{
  "name": "nagara-spike-xs-api",
  "main": "src/index.ts",
  "compatibility_date": "2026-09-01",
  "workflows": [
    { "name": "nagara-spike-xs-item", "binding": "ITEM", "class_name": "ItemWorkflow", "script_name": "nagara-spike-xs-pipeline" }
  ]
}
E
cat > api/src/index.ts <<'E'
export default {
  async fetch(req: Request, env: any) {
    const url = new URL(req.url);
    const id = url.searchParams.get("id");
    try {
      if (req.method === "POST" && url.pathname === "/batch") {
        const ids = (url.searchParams.get("ids") ?? "").split(",");
        const r = await env.ITEM.createBatch(ids.map((id) => ({ id, params: {} })));
        return Response.json({ created: r.map((i: any) => i.id) });
      }
      if (req.method === "POST") {
        const inst = await env.ITEM.create({ id, params: { note: "from api" } });
        return Response.json({ id: inst.id });
      }
      const inst = await env.ITEM.get(id);
      return Response.json(await inst.status());
    } catch (e: any) {
      return Response.json({ error: String(e?.message ?? e), name: e?.name }, { status: 500 });
    }
  },
};
E
for d in pipeline api; do (cd $d && pnpm install >/dev/null 2>&1; echo '{"compilerOptions":{"target":"es2022","module":"esnext","moduleResolution":"bundler","types":["@cloudflare/workers-types"],"strict":false,"skipLibCheck":true}}' > tsconfig.json); done
ls pipeline/node_modules | head -3

